-- Onboarding CMS + accurate canvas. Applied live 2026-09-08.
create table if not exists onboarding_copy (
  key text primary key,
  text text not null,
  updated_at timestamptz not null default now(),
  updated_by text
);
alter table onboarding_copy enable row level security;
drop policy if exists ocopy_read on onboarding_copy;
drop policy if exists ocopy_write on onboarding_copy;
create policy ocopy_read on onboarding_copy for select to anon, authenticated using (true);
create policy ocopy_write on onboarding_copy for all to authenticated using (is_any_staff()) with check (is_any_staff());
on conflict (key) do nothing;

update canvas_docs set doc = $doc${"screens": [{"id": "w1", "flow": "Website sign-up", "x": 60, "y": 60, "title": "Login", "status": "live", "els": [{"t": "emoji", "text": "\ud83d\uddfa"}, {"t": "h", "text": "Collide"}, {"t": "p", "text": "Always something to look forward to.", "key": "auth.tagline"}, {"t": "input", "text": "you@email.com"}, {"t": "btn", "text": "Send me a magic link", "key": "auth.email_btn"}, {"t": "fine", "text": "No passwords. We email you a one-tap link.", "key": "auth.fineprint"}]}, {"id": "w2", "flow": "Website sign-up", "x": 320, "y": 60, "title": "Check email", "status": "live", "els": [{"t": "emoji", "text": "\ud83d\udcec"}, {"t": "h", "text": "Check your email", "key": "auth.sent_title"}, {"t": "p", "text": "We sent a magic link to your inbox. Tap it to come in.", "key": "auth.sent_body"}]}, {"id": "w3", "flow": "Website sign-up", "x": 580, "y": 60, "title": "The Bugle (profile setup)", "status": "live", "els": [{"t": "kicker", "text": "the collide bugle \u00b7 late edition", "key": "onb.masthead"}, {"t": "h", "text": "New arrival in town", "key": "onb.headline"}, {"t": "p", "text": "This just in \u2014 [your name] was seen stepping into town with excellent taste and a wide-open calendar."}, {"t": "input", "text": "(555) 555-0123"}, {"t": "p", "text": "They've claimed [home city] as home turf."}, {"t": "input", "text": "\u2022\u2022\u2022\u2022\u2022\u2022 (6-digit code)"}, {"t": "btn", "text": "Run the story \u2192", "key": "onb.submit"}, {"t": "fine", "text": "Your number stays off the record \u2014 plans only, never spam.", "key": "onb.fineprint"}]}, {"id": "w4", "flow": "Website sign-up", "x": 840, "y": 60, "title": "The map (lands here)", "status": "live", "els": [{"t": "map", "text": "\ud83d\uddfa"}, {"t": "p", "text": "No guided next step \u2014 the user lands on the city map."}, {"t": "pill", "text": "\u26a0 this is where onboarding ends today"}]}, {"id": "i1", "flow": "Event invite", "x": 60, "y": 560, "title": "Shared link unfurl", "status": "live", "els": [{"t": "card", "text": "\ud83d\udd17 collide.city"}, {"t": "h", "text": "The Found Day \u2014 a five-stop hunt"}, {"t": "p", "text": "5 going \u00b7 hosted by Rose Sounds \u2014 join the plan on Collide."}]}, {"id": "i2", "flow": "Event invite", "x": 320, "y": 560, "title": "Invite landing", "status": "live", "els": [{"t": "kicker", "text": "YOU'RE INVITED", "key": "invite.kicker"}, {"t": "h", "text": "The Found Day"}, {"t": "avatars", "text": "Jules, Tommy, Priya + 2 more are in"}, {"t": "pill", "text": "Hosted in Rose Sounds \u00b7 8 members"}, {"t": "toggle", "text": "Also join the community \u2014 this invite vouches you in", "key": "invite.toggle"}, {"t": "btn", "text": "I'm in \u2014 sign me up \ud83d\ude4c", "key": "invite.cta"}]}, {"id": "i3", "flow": "Event invite", "x": 580, "y": 560, "title": "Login (invited variant)", "status": "live", "els": [{"t": "h", "text": "[inviter] invited you \ud83c\udf89"}, {"t": "p", "text": "Join them on Collide \u2014 always something to look forward to."}, {"t": "btn", "text": "Join with a magic link", "key": "auth.invited_btn"}]}, {"id": "i4", "flow": "Event invite", "x": 840, "y": 560, "title": "The Bugle (vouched)", "status": "live", "els": [{"t": "kicker", "text": "the collide bugle \u00b7 late edition", "key": "onb.masthead"}, {"t": "h", "text": "New arrival in town", "key": "onb.headline"}, {"t": "p", "text": "Sources confirm [inviter] vouches for them personally."}, {"t": "btn", "text": "Run the story \u2192", "key": "onb.submit"}]}, {"id": "i5", "flow": "Event invite", "x": 1100, "y": 560, "title": "Auto-join \u2192 event room", "status": "live", "els": [{"t": "emoji", "text": "\ud83c\udf89"}, {"t": "h", "text": "You're in \u2014 both of them"}, {"t": "p", "text": "RSVP + community membership happen on arrival."}, {"t": "btn", "text": "Open the event \u2192"}]}, {"id": "m1", "flow": "Community invite", "x": 60, "y": 1500, "title": "Join landing", "status": "live", "els": [{"t": "emoji", "text": "\ud83c\udfd8\ufe0f"}, {"t": "h", "text": "[Community name]"}, {"t": "p", "text": "[blurb]"}, {"t": "pill", "text": "8 members \u00b7 3 things coming up"}, {"t": "btn", "text": "Join \u2014 you're in the moment you sign up \ud83c\udf9f", "key": "join.cta"}, {"t": "p", "text": "Already on collide? Sign in", "key": "join.signin"}, {"t": "fine", "text": "your city, hand-drawn", "key": "join.foot"}]}, {"id": "m2", "flow": "Community invite", "x": 320, "y": 1500, "title": "Login \u2192 Bugle \u2192 community", "status": "live", "els": [{"t": "p", "text": "Signs up via the same login + Bugle, lands in the community."}]}, {"id": "c1", "flow": "Add to circle", "x": 60, "y": 1060, "title": "Connect sheet", "status": "live", "els": [{"t": "h", "text": "Add to circle"}, {"t": "card", "text": "\u25a6 QR code"}, {"t": "p", "text": "Have them scan this with their phone camera \u2014 or send your link. Works even if they're not on Collide yet: it invites them in, then connects you.", "key": "circle.hint"}, {"t": "btn", "text": "Share my link", "key": "circle.share"}]}, {"id": "c2", "flow": "Add to circle", "x": 320, "y": 1060, "title": "Connected", "status": "live", "els": [{"t": "emoji", "text": "\ud83c\udf89"}, {"t": "h", "text": "You're connected", "key": "circle.done_title"}, {"t": "p", "text": "You and your new friend can now see each other's announcements.", "key": "circle.done_body"}, {"t": "btn", "text": "Add someone else"}]}, {"id": "c3", "flow": "Add to circle", "x": 580, "y": 1060, "title": "On their profile", "status": "live", "els": [{"t": "avatars", "text": "Maya Flows"}, {"t": "btn", "text": "Accept request \ud83e\udd1d"}, {"t": "p", "text": "They'll see your request on their profile."}]}, {"id": "p1", "flow": "Proposed onboarding", "x": 60, "y": 2040, "title": "\u2460 Name & face", "status": "proposed", "els": [{"t": "kicker", "text": "PROPOSED"}, {"t": "h", "text": "Make your face"}, {"t": "p", "text": "Build your notionist avatar \u2014 the first thing your circle sees."}, {"t": "btn", "text": "Next"}]}, {"id": "p2", "flow": "Proposed onboarding", "x": 320, "y": 2040, "title": "\u2461 Home city", "status": "proposed", "els": [{"t": "kicker", "text": "PROPOSED"}, {"t": "h", "text": "Where's home?"}, {"t": "p", "text": "Sets your map, your feed, your people. (Already collected in the Bugle \u2014 surface it clearly.)"}, {"t": "pills", "text": "NYC|ATL|CHI|LA"}]}, {"id": "p3", "flow": "Proposed onboarding", "x": 580, "y": 2040, "title": "\u2462 Turn on nudges", "status": "proposed", "els": [{"t": "kicker", "text": "PROPOSED"}, {"t": "emoji", "text": "\ud83d\udd14"}, {"t": "h", "text": "Don't miss the plan"}, {"t": "p", "text": "Notifications for invites, circle requests, and event chat. One tap."}, {"t": "btn", "text": "Turn on notifications"}]}, {"id": "p4", "flow": "Proposed onboarding", "x": 840, "y": 2040, "title": "\u2463 Find your first people", "status": "proposed", "els": [{"t": "kicker", "text": "PROPOSED"}, {"t": "h", "text": "Start your circle"}, {"t": "p", "text": "Add 2\u20133 people now \u2014 share your link or scan. A circle of 6\u20138 is the whole point."}, {"t": "btn", "text": "Add people"}]}, {"id": "p5", "flow": "Proposed onboarding", "x": 1100, "y": 2040, "title": "\u2464 Join something", "status": "proposed", "els": [{"t": "kicker", "text": "PROPOSED"}, {"t": "h", "text": "Get on a calendar"}, {"t": "p", "text": "Join a community or RSVP to one plan before you land \u2014 so the map isn't empty."}, {"t": "btn", "text": "Show me what's on"}]}]}$doc$::jsonb, name = 'Onboarding flows', updated_at = now(), updated_by = 'seed-real' where id = 'onboarding';
delete from canvas_versions where doc_id = 'onboarding';
